{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('normalizeUrl protocol regex length', () => {
  it('should preserve double slash after protocol-like substring in pathname', () => {
    const longProto = 'a'.repeat(51);
    const url = 'http://example.com/' + '/'+longProto+'://///test';
    const expected = 'http://example.com/' + '/'+longProto+':///test';
    const actual = normalizeUrl(url);
    assert.strictEqual(actual, expected);
  });
});"}
